  input  [31:0] io_in_bits_csr_wdata,
  input         io_in_bits_csr_wen,
  input  [11:0] io_in_bits_csr_waddr,
  input  [31:0] io_in_bits_csr_rdata,
  input         io_in_bits_is_csrrw,
                io_in_bits_is_csrrs,
                io_in_bits_is_lw,
                io_in_bits_is_lbu,
