  reg  [31:0] pc;
  reg  [31:0] inst;
  reg  [31:0] alu_result;
  reg  [31:0] rs2_data;
  reg  [4:0]  rd_addr;
  reg         rd_en;
  reg  [5:0]  load_tag;
  reg  [31:0] csr_wdata;
  reg         csr_wen;
  reg  [11:0] csr_waddr;
  reg  [31:0] csr_rdata;
  reg         is_csrrw;
  reg         is_csrrs;
  reg         is_lbu;
  reg         is_lh;
  reg         is_lhu;
  reg         is_lb;
  reg         is_sw;
  reg         is_sb;
  reg         is_sh;
  reg         is_jalr;
  reg         is_jal;
  reg         is_load;
  reg         is_store;
  reg  [1:0]  state;
  wire        in_ready = state == 2'h0;
  reg         req_sent;
  reg         out_sent;
  wire        _GEN = state == 2'h1;
  wire        io_mem_req_valid_0 = ~in_ready & _GEN & ~req_sent;
  wire        _GEN_0 = io_mem_req_ready & io_mem_req_valid_0;
  wire        _GEN_1 = state == 2'h2;
  wire        io_out_valid_0 = ~in_ready & (_GEN ? req_sent & ~out_sent : _GEN_1);
  wire [3:0]  wmask =
    is_sb ? 4'h1 << alu_result[1:0] : is_sh ? (alu_result[1] ? 4'hC : 4'h3) : {4{is_sw}};
  wire [46:0] wdata =
    is_sb
      ? {8'h0, {31'h0, rs2_data[7:0]} << {34'h0, alu_result[1:0], 3'h0}}
      : is_sh
          ? {31'h0, rs2_data[15:0]} << {42'h0, alu_result[1], 4'h0}
          : {15'h0, is_sw ? rs2_data : 32'h0};
  wire [2:0]  io_mem_req_bits_wsize_0 = {1'h0, is_sb ? 2'h0 : is_sh ? 2'h1 : 2'h2};
  wire        io_mem_req_bits_bypass_0 =
    is_store & ~(alu_result[31:26] == 6'h28 | alu_result[31:26] == 6'h20)
    | pc < 32'hA0010000 & (is_load | is_store);
  `ifndef SYNTHESIS
    always @(posedge clock) begin
      if ((`PRINTF_COND_) & _GEN_0 & is_store
          & (alu_result[31:2] == 30'h20003FF6 | alu_result[31:2] == 30'h20003FF5
             | alu_result[31:2] == 30'h20003FF4 | alu_result[31:2] == 30'h20003FF0
             | alu_result[31:2] == 30'h20003FEF | alu_result[31:2] == 30'h20003FF1)
          & ~reset)
        $fwrite(32'h80000002,
                "[MEM1-WATCH] pc=0x%x inst=0x%x addr=0x%x word=0x%x wdata=0x%x wmask=0x%x wsize=%d bypass=%d\n",
                pc, inst, alu_result, {alu_result[31:2], 2'h0}, wdata, wmask,
                io_mem_req_bits_wsize_0, io_mem_req_bits_bypass_0);
    end // always @(posedge)
