  wire        _GEN_2 = in_ready & io_in_valid;
  wire        _GEN_3 =
    io_in_bits_is_lw | io_in_bits_is_lb | io_in_bits_is_lbu | io_in_bits_is_lh
    | io_in_bits_is_lhu | io_in_bits_is_sw | io_in_bits_is_sb | io_in_bits_is_sh;
  wire        _GEN_4 = _GEN_2 & _GEN_3;
  wire        _GEN_5 = io_out_ready & io_out_valid_0;
  always @(posedge clock) begin
    if (reset) begin
      pc <= 32'h0;
      inst <= 32'h0;
      alu_result <= 32'h0;
      rs2_data <= 32'h0;
      rd_addr <= 5'h0;
      rd_en <= 1'h0;
      load_tag <= 6'h0;
      csr_wdata <= 32'h0;
      csr_wen <= 1'h0;
      csr_waddr <= 12'h0;
      csr_rdata <= 32'h0;
      is_csrrw <= 1'h0;
      is_csrrs <= 1'h0;
      is_lbu <= 1'h0;
      is_lh <= 1'h0;
      is_lhu <= 1'h0;
      is_lb <= 1'h0;
      is_sw <= 1'h0;
      is_sb <= 1'h0;
      is_sh <= 1'h0;
      is_jalr <= 1'h0;
      is_jal <= 1'h0;
      is_load <= 1'h0;
      is_store <= 1'h0;
      state <= 2'h0;
      req_sent <= 1'h0;
      out_sent <= 1'h0;
    end
    else begin
      if (_GEN_2) begin
        pc <= io_in_bits_pc;
        inst <= io_in_bits_inst;
        alu_result <= io_in_bits_alu_result;
        rs2_data <= io_in_bits_rs2_data;
        rd_addr <= io_in_bits_rd_addr;
        rd_en <= io_in_bits_rd_en;
        load_tag <= io_in_bits_load_tag;
        csr_wdata <= io_in_bits_csr_wdata;
        csr_wen <= io_in_bits_csr_wen;
        csr_waddr <= io_in_bits_csr_waddr;
        csr_rdata <= io_in_bits_csr_rdata;
        is_csrrw <= io_in_bits_is_csrrw;
        is_csrrs <= io_in_bits_is_csrrs;
        is_lbu <= io_in_bits_is_lbu;
        is_lh <= io_in_bits_is_lh;
        is_lhu <= io_in_bits_is_lhu;
        is_lb <= io_in_bits_is_lb;
        is_sw <= io_in_bits_is_sw;
        is_sb <= io_in_bits_is_sb;
        is_sh <= io_in_bits_is_sh;
