  assign io_mem_resp_bits_data = _GEN | ~_GEN_4 ? 32'h0 : io_master_rdata;
  assign io_mem_resp_bits_last = ~_GEN & (_GEN_4 ? io_master_rlast : ~_GEN_5 & (&state));
